-- expect (Jest style). Every test name ends with the outcome it must have.

describe("expect", function()
    it("basics (ok)", function()
        expect(1).to.be(1)
        expect({ 1, { 2 } }).to.equal({ 1, { 2 } })
        expect({ a = 1 }).to_not.be({ a = 1 })
        expect(nil).to.be_nil()
        expect(0).to.exist()
        expect(true).to.be_true()
        expect(false).to.be_false()
        expect(false).to.be.falsy()
        expect("").to.be.truthy()
        expect(3).to.be.a("number")
        expect(3).to.be_an("integer")
        expect(3.5).to.be.a("float")
        expect(3).to.be_greater_than(2)
        expect(3).to.be.above(2)
        expect(1).to.be.below(2)
        expect(2).to.be_at_least(2)
        expect(2).to.be_at_most(2)
        expect(1.0).to.be.near(1.04, 0.05)
        expect("abc").to.match("^a")
        expect({ 1, 2 }).to.contain(2)
        expect("hello").to.contain("ll")
        expect({ 1, 2 }).to.have.length(2)
        expect({ x = 1 }).to.have.key("x")
        expect(5).to.satisfy(function(v) return v > 4 end)
        expect(5).to.satisfy(match.is_number())
        expect(function() error("bad thing") end).to.fail("bad thing")
        expect(function() error("bad 12") end).to.throw("bad %d+")
        expect(function() end).never.to.fail()
        expect(1).not_to.be(2)
    end)

    it("equal shows the first difference (fails)", function()
        expect({ a = { 1, 2 } }).to.equal({ a = { 1, 3 } })
    end)

    it("be compares identity (fails)", function()
        expect(1).to.be(2)
    end)

    it("an unknown matcher (errors)", function()
        expect(1).to.be_purple()
    end)

    it("negated (fails)", function()
        expect(1).to_not.be(1)
    end)
end)
